 if(p.jatot) r.push(['Jättöpaikat paluussa',p.jatot]);
 if(p.kohta) r.push(['Kohtaamisohje',p.kohta]);
 if(p.konteksti==='haat'&&p.useita) r.push(['Paluulähdöt',p.paluuajat||'useampi, ajat sovitaan']);
