 r.push(['Matkustajia',p.montako?p.montako+' hlö':'–']);
 if(p.esteeton) r.push(['Esteettömyys','Ryhmässä pyörätuolin käyttäjä tai muu esteettömyystarve'+(p.esteetonLisa?': '+p.esteetonLisa:'')]);
