 if(L!==null&&P!==null){if(L>=P) v.push({laji:'aika',teksti:'Lähtö '+kloMin(L)+' on perillä viimeistään -ajan '+kloMin(P)+' jälkeen.'});
  else if(ajo&&L+ajo>P) v.push({laji:'aika',teksti:'Lähtö '+kloMin(L)+' ei ehdi perille '+kloMin(P)+' mennessä.'+ajoT});}
