// Phase 2: muutospyyntö hyväksyttyyn tai vahvistettuun varaukseen. Pyyntö kirjataan erikseen eikä muuta varauksen tietoja, hintaa tai tilaa.
var MUUTOSLAJIT=['Päivä tai kellonaika','Reitti tai noutopaikat','Matkustajamäärä','Esteettömyys tai erityistarve','Muu muutos'];
function muutospyynnot(p){return p.muutospyynnot||[];}
