/* ---------------------------------------------------------------- vastausaika, laskutustiedot ja Y-tunnus */
/* "Jopa parissa tunnissa" on toimiston lupaus, ja toimisto on avoinna arkisin 8–16 (yhteystiedot-13).
   Toimistoajan ulkopuolella asiakkaalle näytetään vain aukioloaika, ja myynnin laskuri laskee kaksi toimistotuntia. */
var LUPAUS=2*3600*1000, AUKI=8, KIINNI=16, LUETUT='ab-luetut';
/* K-20: arkipyhät, jolloin toimisto ei ole "arkisin" auki: uudenvuodenpäivä, loppiainen, pitkäperjantai, 2. pääsiäispäivä, vappu,
   helatorstai, itsenäisyyspäivä ja joulu. Juhannusaatto ja jouluaatto ovat oletus (yleinen käytäntö), varmistetaan Åbergilta. */
var PYHAT={};
function pyhat(v){if(PYHAT[v]) return PYHAT[v];
 var a=v%19, b=Math.floor(v/100), c=v%100, e=b%4, f=Math.floor((b+8)/25), g=Math.floor((b-f+1)/3), h=(19*a+b-Math.floor(b/4)-g+15)%30,
  l=(32+2*e+2*Math.floor(c/4)-h-c%4)%7, m=Math.floor((a+11*h+22*l)/451), kk=Math.floor((h+l-7*m+114)/31), pv=(h+l-7*m+114)%31+1;
 var lista={}, lisaa=function(t){lista[t.getMonth()+'-'+t.getDate()]=1;};
 [[0,1],[0,6],[4,1],[11,6],[11,24],[11,25],[11,26]].forEach(function(x){lisaa(new Date(v,x[0],x[1]));});
 [-2,1,39].forEach(function(x){lisaa(new Date(v,kk-1,pv+x));});           // pitkäperjantai, 2. pääsiäispäivä, helatorstai
 for(var j=19;j<=25;j++) if(new Date(v,5,j).getDay()===5) lisaa(new Date(v,5,j)); // juhannusaatto
 return (PYHAT[v]=lista);}
function arkipaiva(t){var v=t.getDay(); return v>0&&v<6&&!pyhat(t.getFullYear())[t.getMonth()+'-'+t.getDate()];}
function toimistoAuki(ts){var t=new Date(ts), h=t.getHours(); return arkipaiva(t)&&h>=AUKI&&h<KIINNI;}
function nopea(ts){return toimistoAuki(ts)?T.nopea:T.toimisto;}
// O-18: milloin toimisto seuraavaksi aukeaa, esim. "to 12.11. klo 8"
function aukeaa(ts){var t=new Date(ts);
 for(var i=0;i<20;i++){var alku=new Date(t); alku.setHours(AUKI,0,0,0); if(arkipaiva(t)&&ts<alku.getTime()) return alku.getTime(); t=alku; t.setDate(t.getDate()+1);}
 return t.getTime();}
function viikonpaiva(ts){var t=new Date(ts); return ['su','ma','ti','ke','to','pe','la'][t.getDay()]+' '+t.getDate()+'.'+(t.getMonth()+1)+'.';}
// kuittaus ja sähköposti: toimistoaikana parin toimistotunnin lupaus, muuten milloin pyyntö käsitellään
function kasittely(ts){return toimistoAuki(ts)?T.nopea+'.':T.kiinni+' ('+viikonpaiva(aukeaa(ts))+' klo '+AUKI+').';}
function takaraja(ts){var t=new Date(ts), jaljella=LUPAUS;
 for(var i=0;i<20;i++){var alku=new Date(t), loppu=new Date(t); alku.setHours(AUKI,0,0,0); loppu.setHours(KIINNI,0,0,0);
  if(arkipaiva(t)&&t<loppu){if(t<alku) t=alku; if(loppu-t>=jaljella) return t.getTime()+jaljella; jaljella-=loppu-t;}
  t=alku; t.setDate(t.getDate()+1);}
 return t.getTime();}
function paivaNimi(ts){var t=new Date(ts), n=new Date(), h=new Date(n); h.setDate(h.getDate()+1);
 if(t.toDateString()===n.toDateString()) return 'tänään'; if(t.toDateString()===h.toDateString()) return 'huomenna';
 return ['su','ma','ti','ke','to','pe','la'][t.getDay()]+' '+t.getDate()+'.'+(t.getMonth()+1)+'.';}
function vastausaika(p){if(p.tila==='sopimus') return ['Sopimuspyyntö, '+(TOISTO[p.toisto]||TOISTO.avoin).toLowerCase(),''];
 if(p.tila==='soitto') return ['Soittopyyntö'+(p.soittoaika?': '+p.soittoaika.toLowerCase():''),''];
 if(p.tarjous) return [p.tarjous.auto?'Vastattu heti, automaattinen tarjous':'Vastattu '+kesto(p.tarjous.ts-p.luotu)+' kuluessa','ok'];
 if(p.tila==='hoidettu') return ['Hoidettu','ok'];
 var raja=takaraja(p.luotu), jaljella=raja-Date.now();
 if(jaljella<0) return ['Myöhässä '+kesto(-jaljella),'myoh'];
 return [jaljella<=LUPAUS&&toimistoAuki(Date.now())?'Vastaa '+kesto(jaljella)+' kuluessa':'Vastaa viimeistään '+paivaNimi(raja)+' klo '+kello(raja),''];}
function laskuri(p){var v=vastausaika(p); return '<span class="j-laskuri'+(v[1]?' '+v[1]:'')+'">'+esc(v[0])+'</span>';}
// tarjous on hyväksytty myös, kun ajat odottavat tarkistusta tai varaus on alustava (Mousen 10. arvio)
function hyvaksytty(p){return ['hyvaksytty','tarkistettava','alustava','vahvistettu'].indexOf(p.tila)>=0;}
function myyntiTila(p){var y=eur2(p.tarjous.yht)+' sis. alv.'+(muutosAuki(p).length?' Muutospyyntö odottaa käsittelyä.':''); return p.tila==='vahvistettu'?'Varaus vahvistettu: '+y:p.tila==='alustava'?'Alustava varaus: '+y+' Odottaa tilaajan kellonaikoja.':
 p.tila==='tarkistettava'?'Tilaaja ilmoitti kellonajat: tarkistakaa ajat ja hinta. '+y:'Asiakas hyväksyi tarjouksen: '+y;}
function laskutusRivit(p){var t=p.tilaus; if(!t) return [];
 var r=[['Maksaja',t.maksaja==='yritys'?'Yritys tai yhdistys':'Yksityishenkilö']];
 if(t.maksaja==='yritys'){r.push(['Nimi',t.yritys]); r.push(['Y-tunnus',t.ytunnus+(t.ytj?' (tarkistettu PRH:n datasta)':'')]);}
 else r.push(['Nimi',t.lnimi]);
 r.push(['Laskutusosoite',[t.osoite,[t.postinro,t.toimipaikka].filter(Boolean).join(' ')].filter(Boolean).join(', ')]);
 r.push(['Lasku',t.laskutapa==='verkkolasku'?'Verkkolasku '+t.verkkolasku+', välittäjä '+t.valittaja:'Sähköpostiin '+t.laskusposti]);
 if(t.viite) r.push(['Viite',t.viite]);
 r.push(['Yhteyshenkilö matkalla',[t.yhteyshenkilo,t.yhteyspuh].filter(Boolean).join(', ')]);
 return r;}
function laskutusTeksti(p){return [p.id+' '+reittiTeksti(p)+(p.paiva?', '+pvm(p.paiva):'')].concat(laskutusRivit(p).map(function(x){return x[0]+': '+x[1];}))
 .concat(p.tarjous?['Hinta: '+eur2(p.tarjous.alv0)+' alv 0 %, '+eur2(p.tarjous.yht)+' sis. alv '+luku(p.tarjous.alvp)+' %']:[]).join('\n');}
function ytunnusOk(y){var m=/^(\d{7})-(\d)$/.exec(y||''); if(!m) return false; var w=[7,9,10,5,8,4,2], s=0;
 for(var i=0;i<7;i++) s+=w[i]*+m[1].charAt(i); var r=s%11; return r!==1&&(r===0?0:11-r)===+m[2];}
/* Yrityksen nimi ja osoite PRH:n avoimesta YTJ-rajapinnasta (avoindata.prh.fi, CORS sallittu). */
function haeYritys(y){var c=window.AbortController?new AbortController():null, aj=c?setTimeout(function(){c.abort();},7000):0;
 return fetch('https://avoindata.prh.fi/opendata-ytj-api/v3/companies?businessId='+encodeURIComponent(y),c?{signal:c.signal}:{})
  .then(function(r){if(!r.ok) throw new Error('http'); return r.json();}).then(function(j){clearTimeout(aj); var y0=(j.companies||[])[0]; if(!y0) return null;
   var nimet=(y0.names||[]).filter(function(n){return !n.endDate;}), nimi=nimet.filter(function(n){return String(n.type)==='1';})[0]||nimet[0];
   var os=(y0.addresses||[]).filter(function(a){return a.type===2;})[0]||(y0.addresses||[])[0]||{};
   var kunta=((os.postOffices||[]).filter(function(x){return x.languageCode==='1';})[0]||(os.postOffices||[])[0]||{}).city||'';
   var katu=os.postOfficeBox?'PL '+os.postOfficeBox:[os.street,os.buildingNumber,os.entrance,os.apartmentNumber?os.apartmentNumber+(os.apartmentIdSuffix||''):''].filter(Boolean).join(' ');
   return {nimi:nimi?nimi.name:'',osoite:katu,postinro:os.postCode||'',toimipaikka:kunta?kunta.charAt(0)+kunta.slice(1).toLowerCase():''};});}
function merkitse(x,ok){var k=x.closest('.kentta'); if(k) k.classList.toggle('virhe',!ok); x.setAttribute('aria-invalid',ok?'false':'true'); return ok;}
function tarkistaKentat(juuri){var eka=null; juuri.querySelectorAll('[required]').forEach(function(x){if(x.closest('[hidden]')) return;
  var ok=String(x.value).trim()!==''&&(x.type!=='email'||/.+@.+\..+/.test(x.value))&&(x.name!=='ytunnus'||ytunnusOk(x.value.trim()))&&(x.name!=='postinro'||/^\d{5}$/.test(x.value.trim()));
  if(!merkitse(x,ok)&&!eka) eka=x;});
 if(eka) eka.focus(); return !eka;}

